{"source":"#include <stdio.h>
#include <string.h>
#define maxlen 3005
int main(int argc, char *argv[])
{
   int n;
   char s[maxlen];
   int i,j,k,prei,res;
   while(~scanf("%d",&n))
   {
       getchar();
       gets(s);
       i=res=prei=0;
       while(i<n)
       {
           while(i<n&&s[i]=='.') i++;
           if(i>=n) break;
           if(s[i]=='R')
           {
            res+=i-prei;
            i++;
            prei=i;
            while(i<n&&s[i]=='.') i++;
            if(i>=n) {prei=i;break;}
            else if(((i-prei)%2)==0&&i!=prei) res++;
           }
           prei=++i;
       }
       res+=i-prei;
       printf("%d\n",res);
   }
return 0;
}"}
